 SELECT target,'70e2fe8c-1862-3f79-925d-5209f0721808','びょうきです。きょうは がっこうを（　）。','multiple_choice','vocabulary',3,'ことばと ぶん','（　）に あう ことばを えらんで ください。<details><summary>Petunjuk</summary>Pilih kata yang sesuai dengan konteks.</details>',NULL,NULL,NULL,'がっこうを やすみます berarti tidak masuk sekolah.',4,(q.assessment_meta-'ordered'-'starPosition'-'spokenChoices') || '{"version":"n5-assessment-v4","form":"A","key":"b14-a-jlpt-r2-4","objective":"goal1","itemType":"context_vocabulary","distractorReasons":["Masuk sekolah memakai に; bukan がっこうを はいります.","あいます menyatakan bertemu orang dengan に／と.","たちます berarti berdiri dan tidak membentuk ungkapan absen sekolah.","がっこうを やすみます berarti tidak masuk sekolah."]}'::jsonb,q.audio_scene,q.grammar_id FROM quiz_questions q WHERE q.id='eef52ca6-a9a8-3676-bd99-fefeab747d81';
