 SELECT target,'098a3e0d-8d1a-35c6-8bb7-dc46deaf9454','「きのうは がっこうへ いかなかった。」と おなじ いみの ぶんは どれですか。','multiple_choice','vocabulary',4,'おなじ いみ','おなじ いみの ぶんを えらんで ください。<details><summary>Petunjuk</summary>Pilih ungkapan yang bermakna setara.</details>',NULL,NULL,NULL,'いかなかった dan いきませんでした sama-sama negatif lampau; waktunya tetap kemarin.',6,(q.assessment_meta-'ordered'-'starPosition'-'spokenChoices') || '{"version":"n5-assessment-v4","form":"A","key":"b14-a-jlpt-r2-6","objective":"goal1","itemType":"paraphrase","distractorReasons":["Waktu berubah menjadi hari ini dan tindakan menjadi afirmatif.","いかなかった dan いきませんでした sama-sama negatif lampau; waktunya tetap kemarin.","Afirmatif lampau menyatakan pergi, bukan tidak pergi.","Waktu berubah menjadi besok."]}'::jsonb,q.audio_scene,q.grammar_id FROM quiz_questions q WHERE q.id='ddd21bbf-7dc6-3940-93c8-32e17b383150';
