 SELECT 'a26b25c0-61da-314e-979a-062c94358b9f',target,q.question,q.question_type,q.question_category,q.grammar_id,q.section_number,q.section_label,q.section_instruction,q.audio_script,q.audio_scene,q.passage,q.image_url,q.correct_answer,q.explanation,q.sort_order,q.assessment_meta || '{"version":"n5-assessment-v4","key":"b20-a-jlpt-r2-24"}'::jsonb
 FROM quiz_questions q WHERE q.id='efd05165-e29a-3048-b4ea-cfc1bd4f2463';
 INSERT INTO quiz_options(id,question_id,option_text,is_correct,image_url,sort_order)
 SELECT md5(id::text||':n5-assessment-v4')::uuid,'a26b25c0-61da-314e-979a-062c94358b9f',option_text,is_correct,image_url,sort_order FROM quiz_options WHERE question_id='efd05165-e29a-3048-b4ea-cfc1bd4f2463';
